PRAGMA foreign_keys=ON;
CREATE TABLE responses(id TEXT PRIMARY KEY,post_id TEXT NOT NULL,author_id TEXT NOT NULL,status TEXT NOT NULL); CREATE TABLE conversations(id TEXT PRIMARY KEY,response_id TEXT NOT NULL UNIQUE REFERENCES responses(id)); CREATE TABLE conversation_members(conversation_id TEXT REFERENCES conversations(id),user_id TEXT NOT NULL,PRIMARY KEY(conversation_id,user_id)); CREATE TABLE messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL,sender_id TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(conversation_id,sender_id) REFERENCES conversation_members(conversation_id,user_id));
CREATE TABLE blocks(blocker_id TEXT NOT NULL,blocked_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(blocker_id,blocked_id)); CREATE TABLE reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,status TEXT NOT NULL); CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,dedupe_key TEXT NOT NULL,kind TEXT NOT NULL,read_at TEXT,digest_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,UNIQUE(user_id,dedupe_key)); CREATE TABLE funnel_events(id TEXT PRIMARY KEY,event_name TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(event_name,entity_type,entity_id));
